# 兰溪花市订花小程序 - 报价与拣货模块
from dataclasses import dataclass


@dataclass
class BouquetSpec:
    花材: list
    包装: str
    数量: int


def build_floral_picklist(spec: BouquetSpec) -> list:
    """按花束规格生成拣货单，供花艺台备货。"""
    items = []
    for name in spec.花材:
        items.append("%s x%d" % (name, spec.数量))
    return items


def format_quote_display(total_cents: int) -> str:
    """把分为单位的金额渲染成展示文本。"""
    return "￥%.2f" % (total_cents / 100)

